import{it as e,n as t,rt as n,vt as r}from"./chunks/framework.BQh0MzVE.js";var i=JSON.parse(`{"title":"Per-query observability metrics","description":"","frontmatter":{},"headers":[],"relativePath":"pages/advanced/per_query_metrics.md","filePath":"pages/advanced/per_query_metrics.md"}`),a={name:`pages/advanced/per_query_metrics.md`};function o(t,i,a,o,s,c){return r(),n(`div`,null,[...i[0]||=[e(`<h1 id="per-query-observability-metrics" tabindex="-1">Per-query observability metrics <a class="header-anchor" href="#per-query-observability-metrics" aria-label="Permalink to “Per-query observability metrics”">​</a></h1><p>When <code>global.enable_query_metrics</code> is set to true, every scrape emits two additional gauges per query in the configuration:</p><ul><li><code>query_duration_seconds{query=&quot;&lt;query_name&gt;&quot;}</code> - wall-clock time the query took during the most recent scrape, including row scanning. Emitted even when the query errors, so spikes preceding a failure remain visible.</li><li><code>query_rows_returned{query=&quot;&lt;query_name&gt;&quot;}</code> — number of rows the database returned during the most recent scrape. Errored or skipped rows are not counted.</li></ul><p>Both metrics inherit the same constant labels as <code>up</code> / <code>scrape_duration_seconds</code> (notably <code>target</code> in multi-target / jobs mode), so they can be aggregated by target the same way. The feature is off by default to keep the existing metric surface unchanged.</p>`,4)]])}var s=t(a,[[`render`,o]]);export{i as __pageData,s as default};